const webhookItem = $('Webhook1').first()?.json ?? {};
const job = webhookItem.body ?? webhookItem;
const event = String(job?.event || '').toLowerCase();

if (event !== 'job_created') {
  return [];
}

if (!job || !job.job_id) {
  throw new Error(`Missing job_id from webhook payload. Keys: ${Object.keys(job || {}).join(', ')}`);
}

const jobId = Number(job.job_id);
const jobTitle = String(job.title || '').toLowerCase();

let reqSkillsRaw = job.skills_required ?? job.required_skills ?? [];
if (typeof reqSkillsRaw === 'string') {
  try {
    reqSkillsRaw = JSON.parse(reqSkillsRaw);
  } catch {
    reqSkillsRaw = [reqSkillsRaw];
  }
}
if (!Array.isArray(reqSkillsRaw) && typeof reqSkillsRaw === 'object' && reqSkillsRaw !== null) {
  reqSkillsRaw = Object.values(reqSkillsRaw);
}
const reqSkills = reqSkillsRaw
  .map((s) => String(s).toLowerCase().trim())
  .filter(Boolean);

const candidates = $input.all().map((item) => item.json);
const matchedCandidates = [];

const eduLevels = [
  { name: 'doctorate', keywords: ['phd', 'doctorate', 'doctor of'] },
  { name: 'masters', keywords: ['master', 'ms ', 'ma ', 'mba'] },
  { name: 'bachelors', keywords: ['bachelor', 'bs ', 'ba ', 'graduate of', 'degree in', 'college grad'] },
  { name: 'vocational', keywords: ['vocational', 'tesda', 'certificate'] },
  { name: 'highschool', keywords: ['high school', 'secondary'] },
];

for (const candidate of candidates) {
  const resume = String(candidate.resume_text || '').toLowerCase();
  if (resume.length < 5) continue;

  let score = 0;
  const matchedDetails = [];

  let inferredLevel = 'Not clearly stated';
  for (const level of eduLevels) {
    if (level.keywords.some((key) => resume.includes(key))) {
      inferredLevel = level.name;
      score += 30;
      matchedDetails.push(`Degree Level found: ${level.name}`);
      break;
    }
  }

  const alignmentKeywords = jobTitle.split(/\s+/).filter((word) => word.length > 3);
  if (alignmentKeywords.some((word) => resume.includes(word))) {
    score += 30;
    matchedDetails.push(`Field aligned with Job Title: "${jobTitle}"`);
  }

  let skillCount = 0;
  for (const skill of reqSkills) {
    if (resume.includes(skill)) skillCount++;
  }

  const skillScore = reqSkills.length > 0 ? (skillCount / reqSkills.length) * 40 : 0;
  score += skillScore;
  if (skillCount > 0) matchedDetails.push(`${skillCount} skills found in resume text`);

  const matchScore = Math.round(Math.min(score, 100));

  matchedCandidates.push({
    job_id: jobId,
    user_id: candidate.id,
    name: candidate.name,
    email: candidate.email,
    matchScore,
    inferred_edu: inferredLevel,
    reason: matchedDetails.length > 0 ? matchedDetails.join(' | ') : 'No direct matches found',
  });
}

matchedCandidates.sort((a, b) => b.matchScore - a.matchScore);

return matchedCandidates.map((match) => ({ json: match }));
